#!/usr/bin/env python3
"""
Installer for Phase 11 (PR #14): Context Compression, Fast Mode & Insights Subsystem
===================================================================================
This script creates/updates all files for dream/compression/, dream/insights/ and test suites.
Run this script from the root of your Dream repository:
    python apply_pr14.py
"""

import base64
import json
from pathlib import Path

B64_PAYLOAD = ""

def main():
    root = Path.cwd()
    print("🚀 Applying Phase 11: Compression, Fast-Mode & Insights (dream/compression/, dream/insights/)...")
    raw_bytes = base64.b64decode(B64_PAYLOAD.encode("ascii"))
    files = json.loads(raw_bytes.decode("utf-8"))
    for rel_path, content in files.items():
        dest = root / rel_path
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(content, encoding="utf-8")
        print(f"  ✅ Created/Updated: {rel_path}")
    print("\n🎉 PR #14 files successfully installed!")
    print("Run tests with: pytest tests/test_compression_and_insights.py tests/test_compaction.py tests/test_context_compression.py")

if __name__ == "__main__":
    main()
